const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-136.325766, 69.954148);
  const date1 = '2012-06-14';
  const date2 = '2012-07-05';
  const collectionName = 'MODIS/061/MOD09GA'; // Daily Surface Reflectance

  // 2. Data Acquisition & Processing Function
  const getTurbidityProxy = function(date) {
    const collection = ee.ImageCollection(collectionName)
      .filterDate(date)
      .filterBounds(point);

    const image = collection.first();

    if (image) {
      // Use the State QA band for cloud masking. We want clear conditions.
      // Bits 0-1: Cloud State (00 = clear)
      // Bit 10: Internal Cloud Algorithm Flag (0 = no cloud)
      const qa = image.select('state_1km');
      const cloudMask = qa.bitwiseAnd(3).eq(0) // Bits 0-1 are 0
                          .and(qa.bitwiseAnd(1 << 10).eq(0)); // Bit 10 is 0

      // We use the Red band (sur_refl_b01) as a proxy for turbidity.
      // Higher reflectance suggests more suspended sediment.
      return image.select('sur_refl_b01').updateMask(cloudMask);
    }
    return null; // Return null if no image found
  };

  // 3. Calculation for each date
  const image1 = getTurbidityProxy(date1);
  const image2 = getTurbidityProxy(date2);

  if (!image1 || !image2) {
    console.log("No daily MODIS image found for one or both dates.");
    console.log("A"); // The provided dates are invalid for this collection
    return;
  }

  const reduceParams = {
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: point,
    scale: 1000,
    maxPixels: 1e9
  };

  const stats1 = image1.reduceRegion(reduceParams).getInfo();
  const stats2 = image2.reduceRegion(reduceParams).getInfo();

  const val1 = stats1['sur_refl_b01_mean'];
  const count1 = stats1['sur_refl_b01_count'];
  const val2 = stats2['sur_refl_b01_mean'];
  const count2 = stats2['sur_refl_b01_count'];

  // 4. Validation & Final Answer
  console.log(`2012-06-14 Reflectance (Proxy): ${val1 !== null ? val1.toFixed(4) : 'N/A'}, Pixels: ${count1}`);
  console.log(`2012-07-05 Reflectance (Proxy): ${val2 !== null ? val2.toFixed(4) : 'N/A'}, Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("No valid (cloud-free) pixels found for one or both dates at the location.");
    console.log("C2");
    return;
  }

  if (val1 === null || val2 === null) {
    console.log("Calculation failed, result is null.");
    console.log("C3");
    return;
  }

  if (val2 > val1) {
    console.log("Conclusion: Turbidity proxy (reflectance) increased.");
    console.log("A");
  } else {
    console.log("Conclusion: Turbidity proxy (reflectance) did not increase.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
